DECLARE unknown int; moved int;
BEGIN
  SELECT count(*) INTO unknown FROM candidates c WHERE c.election_id IN ('e5f6a7b8-c9d0-1234-ef01-456789012011', 'e5f6a7b8-c9d0-1234-ef01-456789012016', 'e5f6a7b8-c9d0-1234-ef01-456789012021')
    AND NOT EXISTS (SELECT 1 FROM tn_old_seed o WHERE o.id = c.id);
  SELECT count(*) INTO moved FROM candidates c JOIN tn_old_seed o ON o.id = c.id WHERE c.party_id IS DISTINCT FROM o.party_id;
  IF unknown > 0 OR moved > 0 THEN
    RAISE EXCEPTION 'seed_tn_corrections_v1: % Tamil Nadu candidates are not in the old seeds and % changed party since; reconcile them first (docs/DEPLOYMENT.md 5.0a)', unknown, moved;
  END IF;
END $$;

